	FAIL: pc.red('✘'),
	SUCCESS: pc.green('✔'),
	TIMER: pc.red('⏳'),
	START: pc.dim(pc.bold('▶︎')),
	END: pc.dim(pc.bold('■')),
	ERR: pc.red(pc.bold('ERR')),
	WARN: pc.yellow(pc.bold('WRN')),
	LOG: pc.cyan(pc.bold('LOG')),
	DBG: pc.magenta(pc.bold('DBG')),
	INFO: pc.blue(pc.bold('INFO')),
};

